<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { useI18n } from 'vue-i18n'; import { api, type Issue, type PullRequest, type WikiPage } from '../lib/api'; import StatusState from '../components/StatusState.vue'
const route = useRoute(); const { t } = useI18n(); const owner = computed(() => String(route.params.owner)); const repo = computed(() => String(route.params.repo)); const section = computed(() => String(route.params.section || 'code')); const issues = ref<Issue[]>([]); const pulls = ref<PullRequest[]>([]); const wiki = ref<WikiPage[]>([]); const loading = ref(true); const error = ref('')
async function load() { loading.value = true; error.value = ''; try { if (section.value === 'issues') issues.value = await api.issues(owner.value, repo.value); else if (section.value === 'pulls') pulls.value = await api.pulls(owner.value, repo.value); else if (section.value === 'wiki') wiki.value = await api.wiki(owner.value, repo.value) } catch { error.value = '' } finally { loading.value = false } }; onMounted(load)
</script>
<template><section class="page repo-page"><RouterLink class="back-link" to="/dashboard">← {{ t('back') }}</RouterLink><div class="repo-title"><div class="repo-icon large">E</div><div><p class="eyebrow">{{ owner }} / REPOSITORY</p><h1>{{ repo }}</h1><p class="muted">A repository at the edge.</p></div><button class="button ghost">{{ t('settings') }}</button></div><nav class="repo-tabs"><RouterLink :class="{ active: section === 'code' }" :to="`/${owner}/${repo}`">{{ t('code') }}</RouterLink><RouterLink :class="{ active: section === 'issues' }" :to="`/${owner}/${repo}/issues`">{{ t('issues') }} <small>0</small></RouterLink><RouterLink :class="{ active: section === 'pulls' }" :to="`/${owner}/${repo}/pulls`">{{ t('pulls') }} <small>0</small></RouterLink><RouterLink :class="{ active: section === 'wiki' }" :to="`/${owner}/${repo}/wiki`">{{ t('wiki') }}</RouterLink></nav><div class="content-card"><StatusState :loading="loading" :error="error" :empty="false" @retry="load" /><template v-if="!loading && section === 'code'"><div class="code-toolbar"><code>main</code><span>README.md · 2 hours ago</span></div><div class="file-row"><span>◇</span><strong>README.md</strong><span class="muted">A repository at the edge.</span></div><div class="file-row"><span>◇</span><strong>src</strong><span class="muted">latest commit</span></div></template><template v-else-if="!loading && section === 'issues'"><div v-for="issue in issues" :key="issue.number" class="item-row"><span class="number">#{{ issue.number }}</span><strong>{{ issue.title }}</strong><span class="badge open">{{ issue.state }}</span><small>{{ issue.author }}</small></div><div v-if="!issues.length" class="state">{{ t('empty') }}</div></template><template v-else-if="!loading && section === 'pulls'"><div v-for="pull in pulls" :key="pull.number" class="item-row"><span class="number">#{{ pull.number }}</span><strong>{{ pull.title }}</strong><span class="badge open">{{ pull.state }}</span><small>{{ pull.head }} → {{ pull.base }}</small></div><div v-if="!pulls.length" class="state">{{ t('empty') }}</div></template><template v-else-if="!loading && section === 'wiki'"><div v-for="page in wiki" :key="page.slug" class="item-row"><span class="wiki-mark">W</span><strong>{{ page.title }}</strong><small>{{ page.excerpt }}</small></div><div v-if="!wiki.length" class="state">{{ t('empty') }}</div></template></div></section></template>
